const body = $json.body || $json;

if (!body.document_code) {
  throw new Error('document_code is required');
}

// Engineering Documents are immutable (MWO-LTSA-040B Business Rule); new
// revisions must create new document records via Create, not mutate an
// existing one. status is a lifecycle marker, not part of the document's
// substantive identity, and is the only field this workflow may change --
// document_type, title, revision, document_number, and every other field
// are intentionally excluded from the updatable set below.
const updatable = ['status'];

const fields = {};
for (const key of updatable) {
  if (body[key] !== undefined) {
    fields[key] = body[key];
  }
}

if (Object.keys(fields).length === 0) {
  throw new Error('status is the only updatable field for an Engineering Document; at least one updatable field is required');
}

return [{
  json: {
    document_code: body.document_code,
    fields
  }
}];

const { document_code, fields } = $json;
const keys = Object.keys(fields);

const setClauses = keys.map((key, idx) => `${key} = $${idx + 1}`);
setClauses.push('updated_at = NOW()');

const params = keys.map((key) => fields[key]);
params.push(document_code);

const query = `UPDATE seal_engineering_document SET ${setClauses.join(', ')} WHERE document_code = $${params.length} RETURNING *;`;

return [{
  json: {
    document_code,
    query,
    params
  }
}];

const row = $input.first()?.json;

if (!row || !row.document_code) {
  return [{
    json: {
      statusCode: 404,
      success: false,
      message: 'Engineering document not found',
      data: null
    }
  }];
}

return [{
  json: {
    statusCode: 200,
    success: true,
    message: 'Engineering document updated successfully',
    data: row
  }
}];
